const fs = require('fs');
const tokens = fs.readFileSync(0, 'utf8').split(/\s+/).filter(t => t.length > 0);
let idx = 0;
const N = +tokens[idx++], M = +tokens[idx++], K = +tokens[idx++];

const water = [], road = [];
for (let i = 0; i < M; i++) {
  const a = +tokens[idx++], b = +tokens[idx++], t = +tokens[idx++];
  if (t === 1) water.push(a, b);
  else road.push(a, b);
}

const parent = new Int32Array(N + 1);
for (let i = 0; i <= N; i++) parent[i] = i;

function find(x) {
  let r = x;
  while (parent[r] !== r) r = parent[r];
  while (parent[x] !== r) { const nx = parent[x]; parent[x] = r; x = nx; }
  return r;
}

// Há K anos atrás existiam todas as hidrovias e (rodovias atuais - no máximo K).
// O mapa antigo (todas hidrovias + rodovias restantes) precisa ser uma floresta.
// Hidrovias fechando ciclo -> impossível (não podem ser removidas).
let ok = true;

// Processa hidrovias: todas devem ser mantidas.
for (let i = 0; i < water.length; i += 2) {
  const ra = find(water[i]), rb = find(water[i + 1]);
  if (ra === rb) { ok = false; break; }
  parent[ra] = rb;
}

let removed = 0;
if (ok) {
  // Rodovias: mantém as que unem componentes distintas, remove as que fecham ciclo.
  for (let i = 0; i < road.length; i += 2) {
    const ra = find(road[i]), rb = find(road[i + 1]);
    if (ra === rb) removed++;
    else parent[ra] = rb;
  }
}

console.log(ok && removed <= K ? 'S' : 'N');
